import java.util.*;

class Solution {
  public int minimumCoins(int[] prices) {
    int n = prices.length;
    int[] dp = new int[n + 2];
    for (int i = n; i >= 1; i--) {
      int end = Math.min(n + 1, 2 * i + 1);
      int best = Integer.MAX_VALUE;
      for (int j = i + 1; j <= end; j++) best = Math.min(best, dp[j]);
      dp[i] = prices[i - 1] + best;
    }
    return dp[1];
  }
}
